nt-size:32px;line-height:1.2;letter-spacing:-1.2px;margin:12px 0 7px;font-weight:800}.ws-stat p{color:var(--ws-muted);font-size:11px;line-height:1.5}.ws-stat-icon{width:45px;height:45px;border-radius:13px;display:grid;place-items:center;flex-shrink:0}.ws-stat-icon.violet{background:#efedff;color:#6057d9}.ws-stat-icon.teal{background:#e3f7f3;color:#159981}.ws-stat-icon.orange{background:#fff2e6;color:#e39542}.ws-lower-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(290px,.85fr);gap:20px;align-items:start}.ws-panel{background:var(--ws-panel);border:1px solid var(--ws-line);border-radius:18px;padding:25px;min-width:0}.ws-panel + .ws-panel{margin-top:0}.ws-section-head{justify-content:space-between;gap:16px;margin-bottom:20px}.ws-section-title{gap:10px}.ws-title-icon{width:34px;height:34px;display:grid;place-items:center;border-radius:10px;background:#f0efff;color:#6157d8}.ws-title-icon .ws-svg{width:17px;height:17px}.ws-section-head h2{font-family:Manrope,'DM Sans',sans-serif;font-size:16px;letter-spacing:-.4px}.ws-section-head p{font-size:11px;color:var(--ws-muted);margin-top:5px;line-height:1.5}.ws-mini-count{background:#f5f6fc;border:1px solid var(--ws-line);border-radius:9px;padding:7px 10px;font-size:11px;color:var(--ws-muted);font-weight:800;white-space:nowrap}.ws-quick-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.ws-quick-link{gap:12px;min-width:0;border:1px solid var(--ws-line);background:var(--ws-panel);padding:14px 12px;border-radius:12px;transition:.2s}.ws-quick-link:hover{border-color:#bbb5f5;background:rgba(99,91,223,.035);transform:translateY(-2px)}.ws-quick-symbol{width:38px;height:38px;display:grid;place-items:center;border-radius:11px;background:#f0efff;color:#635bdf;flex-shrink:0}.ws-quick-symbol .ws-svg{width:18px;height:18px}.ws-quick-info{min-width:0;flex:1}.ws-quick-info strong{display:block;white-space:nowrap;text-overflow:ellipsis;overflow:hidden;font-size:12px;color:var(--ws-text)}.ws-quick-info smal